// See code-nodes/get-weekly-tab-name.js for annotated version

function getISOWeekLabel(date) {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  d.setDate(d.getDate() + 4 - (d.getDay() || 7));
  const yearStart = new Date(d.getFullYear(), 0, 1);
  const weekNo = Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
  return `W${d.getFullYear()}-${String(weekNo).padStart(2, '0')}`;
}

return [{ json: { tabName: getISOWeekLabel(new Date()) } }];

// See code-nodes/channel-router.js for annotated version
// NOTE: uses actual source sheet column names (Email, 'Founder Linkedin'), NOT canonical names.
// Canonical renaming happens later in 'Coalesce & Normalize'.

function isValidLinkedInProfile(s) {
  if (!s) return false;
  const v = String(s).toLowerCase().trim();
  return v.includes('linkedin.com/in/') || v.includes('linkedin.com/pub/');
}

function getChannel(record) {
  const hasEmail    = !!(record.Email || '').trim();
  const hasLinkedIn = isValidLinkedInProfile(record['Founder Linkedin']);
  if (hasEmail && hasLinkedIn)  return 'email_linkedin';
  if (hasLinkedIn && !hasEmail) return 'linkedin_only';
  if (hasEmail && !hasLinkedIn) return 'email_only';
  return 'none';
}

return items.map(item => ({
  json: { ...item.json, channel: getChannel(item.json) }
}));

// See code-nodes/merge-ai-personalization.js for annotated version
// Parses AI JSON output and promotes personalized fields onto the item.
// Falls back to safe defaults on parse error.

function parsePersonalization(raw) {
  if (!raw) return { email: '', linkedin: '' };
  const cleaned = String(raw).replace(/```json|```/g, '').trim();
  try {
    const obj = JSON.parse(cleaned);
    return {
      email:    (obj.email    || '').trim(),
      linkedin: (obj.linkedin || '').trim(),
    };
  } catch {
    return {
      email:    'Your work in this space stood out to us.',
      linkedin: 'your sector',
    };
  }
}

return items.map(item => {
  const p = parsePersonalization(item.json.output);
  const { output, ...rest } = item.json;
  return {
    json: {
      ...rest,
      personalized_email:    p.email,
      personalized_linkedin: p.linkedin,
    },
  };
});

