// See code-nodes/coalesce-normalize.js for annotated version
// Renames non-canonical source sheet headers to canonical names.
// Also coalesces in case any items slipped through unpaired.

const merged = {};
for (const item of items) {
  for (const [k, v] of Object.entries(item.json)) {
    if (!(k in merged)) {
      merged[k] = v;
    } else if ((merged[k] === '' || merged[k] === null || merged[k] === undefined) &&
               v !== '' && v !== null && v !== undefined) {
      merged[k] = v;
    }
  }
}

const fieldMap = {
  'Pitchbook':        'pitchbook_url',
  'Url':              'website_url',
  'Email':            'email',
  'Founder Linkedin': 'linkedin_url',
  'About':            'about',
  'Date Added':       'date_added',
  'Contacted':        'contacted_at',
};
for (const [old, canonical] of Object.entries(fieldMap)) {
  if (old in merged) {
    if (!(canonical in merged) || merged[canonical] === '' || merged[canonical] === null) {
      merged[canonical] = merged[old];
    }
    delete merged[old];
  }
}

return [{ json: merged }];
